"""Source-preserving transcription of two supplied books. No automatic vocalization."""
from pathlib import Path
import json,re,hashlib,unicodedata
ROOT=Path(__file__).resolve().parents[1]; SITE=ROOT/'public/site'; OUT=SITE/'transcriptions';OUT.mkdir(exist_ok=True)
Q=json.loads((SITE/'quran-source.json').read_text(encoding='utf-8'))['data']['surahs']
def norm(s):
 s=unicodedata.normalize('NFKC',s)
 s=re.sub(r'[\u0610-\u061a\u064b-\u065f\u0670\u06d6-\u06edـ]','',s)
 return s.translate(str.maketrans({'ٱ':'ا','أ':'ا','إ':'ا','آ':'ا','ى':'ي'}))
def q(s,a,start=None,end=None):
 words=Q[s-1]['ayahs'][a-1]['text'].split()
 if s!=1 and a==1 and norm(' '.join(words[:4]))=='بسم الله الرحمن الرحيم':words=words[4:]
 indexed=[(i,norm(w)) for i,w in enumerate(words) if norm(w)];flat=' '.join(w for _,w in indexed)
 lo=0;hi=len(words)
 if start:
  phrase=norm(start);pos=flat.index(phrase);n=len(flat[:pos].split());lo=indexed[n][0]
 if end:
  phrase=norm(end);pos=flat.index(phrase)+len(phrase);n=len(flat[:pos].split());hi=indexed[n-1][0]+1
 return ' '.join(words[lo:hi])
def qr(s,a,b):return ' ۝ '.join(q(s,n) for n in range(a,b+1))
def resolve(s):
 def match(m):
  spec=m.group(1).split('|'); nums=spec[0].split(':');args=[int(x) for x in nums]
  if len(args)==3:return qr(*args)
  return q(*args,start=spec[1] if len(spec)>1 and spec[1] else None,end=spec[2] if len(spec)>2 and spec[2] else None)
 return re.sub(r'\{Q:([^}]+)\}',match,s).strip()
